const COLORS=['#ff4d6d','#ffd23f','#3ec1ff','#7bff6b','#c77dff','#ff9f1c'];
function reset(){score=0;left=ARROWS;popped=0;combo=0;spawnT=0;arrows=[];balloons=[];parts=[];floats=[];for(let i=0;i<6;i++)spawn(Math.random()*H)}
function spawn(y){const gold=Math.random()<.12;balloons.push({x:420+Math.random()*480,y:y??H+40,r:gold?18:24+Math.random()*6,vy:-(0.6+Math.random()*0.9)*(gold?1.8:1),ph:Math.random()*6,c:gold?'#ffe066':COLORS[Math.random()*COLORS.length|0],gold})}
function aim(){const dx=mouse.x-AX,dy=mouse.y-AY;return Math.atan2(dy,dx)}
